optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..543e7d5f 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -137,7 +137,33 @@ pub fn parse(source: &str, root: &str) -> Result<Value> {
     }
     node(element, 0)
 }
+thread_local! {
+    static ENCODED_TIMELINES: std::cell::RefCell<std::collections::VecDeque<(Value, Vec<u8>)>> = const { std::cell::RefCell::new(std::collections::VecDeque::new()) };
+}
 fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
+    if name != "timeline" { return emit_uncached(writer, name, value); }
+    let found = ENCODED_TIMELINES.with(|cache| {
+        let cache = cache.borrow();
+        if let Some((_, bytes)) = cache.iter().find(|(prior, _)| prior == value) {
+            writer.get_mut().extend_from_slice(bytes);
+            true
+        } else { false }
+    });
+    if found { return Ok(()); }
+    let mut temporary = Writer::new(Vec::new());
+    emit_uncached(&mut temporary, name, value)?;
+    let bytes = temporary.into_inner();
+    writer.get_mut().extend_from_slice(&bytes);
+    if bytes.len() <= 4 * 1024 * 1024 {
+        ENCODED_TIMELINES.with(|cache| {
+            let mut cache = cache.borrow_mut();
+            while cache.len() >= 8 || cache.iter().map(|(_, b)| b.len()).sum::<usize>() + bytes.len() > 16 * 1024 * 1024 { cache.pop_front(); }
+            cache.push_back((value.clone(), bytes));
+        });
+    }
+    Ok(())
+}
+fn emit_uncached(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
     if !name
         .chars()
         .all(|c| c.is_ascii_alphanumeric() || "_-".contains(c))
@@ -591,6 +617,17 @@ mod tests {
         for source in ["<!DOCTYPE test SYSTEM 'file:///etc/passwd'><test schema_version='1'/>","<test schema_version='1' xmlns:xi='http://www.w3.org/2001/XInclude'><xi:include href='file:///etc/passwd'/></test>"]{assert!(parse(source,"test").is_err());}
     }
     #[test]
+    fn timeline_cache_matches_uncached_and_rechecks_mutation() {
+        let mut value = serde_json::json!({"entry":[{"event":"<&\"' é", "sequence":1}]});
+        for sequence in [1, 1, 2, 2] {
+            value["entry"][0]["sequence"] = serde_json::json!(sequence);
+            let mut direct = Writer::new(Vec::new());
+            emit_uncached(&mut direct, "timeline", &value).unwrap();
+            assert_eq!(fragment("timeline", &value).unwrap(), direct.into_inner());
+        }
+        assert!(fragment("timeline", &serde_json::json!({"event":"\u{0001}"})).is_err());
+    }
+    #[test]
     fn escaping_roundtrip() {
         let v = serde_json::json!({"explanation":"<&\"' hello"});
         let bytes = encode("test", &v).unwrap();
